(LM.QUIZZES = LM.QUIZZES || {})["a2-functions-describing"] = {"version":1,"id":"a2-functions-describing","topic":"a2-functions-describing","level":"A2","title":"Stop: describing","passScore":3,"items":[{"id":"a2-functions-describing-q1","type":"multiple-choice","kind":"form","prompt":"Mi padre ___ los ojos azules.","options":["es","está","tiene","hay"],"correct":2,"explanation":"Features (eyes, hair) take tener and the article: tiene los ojos azules.","optionNotes":["Ser + eyes is not possible: say tiene.","Estar is for location and states, not features.",null,"Hay means “there is”."]},{"id":"a2-functions-describing-q2","type":"multiple-choice","kind":"function","prompt":"You want to know what your friend's new apartment is like (Spain). You ask:","options":["¿Cómo es tu piso nuevo?","¿Qué es tu piso nuevo?","¿Cómo tiene tu piso nuevo?","¿Cuál es tu piso nuevo?"],"correct":0,"explanation":"“What is it like?” is ¿Cómo es…?","optionNotes":[null,"¿Qué es…? asks for a definition.","This is not Spanish.","¿Cuál es…? asks which one."]},{"id":"a2-functions-describing-q3","type":"multiple-choice","kind":"form","prompt":"Pablo es una persona muy ___.","options":["simpático","simpática","simpáticos","simpáticas"],"correct":1,"explanation":"The adjective agrees with persona, which is feminine, also for a man.","optionNotes":["The adjective agrees with persona (feminine), not with Pablo.",null,"Persona is singular.","Persona is singular."]},{"id":"a2-functions-describing-q4","type":"multiple-choice","kind":"function","prompt":"The table is made of wood:","options":["La mesa es de madera.","La mesa está de madera.","La mesa tiene madera.","La mesa es madera."],"correct":0,"explanation":"What something is made of: ser de + material.","optionNotes":[null,"The material takes ser, not estar.","Tiene madera means “it has wood (in it)”.","The material needs de."]}]};
(LM.QUIZZES = LM.QUIZZES || {})["a2-functions-weekend-vacation"] = {"version":1,"id":"a2-functions-weekend-vacation","topic":"a2-functions-weekend-vacation","level":"A2","title":"Stop: last weekend","passScore":3,"items":[{"id":"a2-functions-weekend-vacation-q1","type":"multiple-choice","kind":"function","prompt":"Monday morning. You ask a friend about the weekend that just ended:","options":["¿Qué tal el fin de semana?","¿Qué haces los fines de semana?","¿Qué vas a hacer el fin de semana?","¿Cómo estás el fin de semana?"],"correct":0,"explanation":"¿Qué tal el fin de semana? asks how a weekend went.","optionNotes":[null,"This asks what your friend usually does on weekends.","This asks about plans for the next weekend.","This is not a natural question."]},{"id":"a2-functions-weekend-vacation-q2","type":"multiple-choice","kind":"function","prompt":"You had a great time at a party. You say:","options":["Tuve un buen tiempo.","Lo pasé muy bien.","Hizo muy buen tiempo.","Me pasó muy bien."],"correct":1,"explanation":"“Have a good time” is pasarlo bien (Latin America also: pasarla bien): Lo pasé muy bien.","optionNotes":["A word-for-word translation of “I had a good time”; Spanish does not say this.",null,"This means “The weather was very good”.","Me pasó means “it happened to me”; this is not Spanish."]},{"id":"a2-functions-weekend-vacation-q3","type":"multiple-choice","kind":"function","prompt":"—Fui a Cuba de vacaciones y lo pasé genial.\n—___","options":["¡Qué pena!","¡Qué suerte!","¿Qué vas a hacer?","De nada."],"correct":1,"explanation":"¡Qué suerte! (Lucky you!) reacts to good news.","optionNotes":["¡Qué pena! reacts to bad news.",null,"This asks about plans, not about the trip.","De nada answers gracias."]},{"id":"a2-functions-weekend-vacation-q4","type":"multiple-choice","kind":"function","prompt":"___ fuimos al museo, después comimos y al final volvimos al hotel.","options":["Primero","Al final","Porque","Pero"],"correct":0,"explanation":"A story starts with primero, goes on with después or luego and ends with al final.","optionNotes":[null,"Al final is for the last action, and the sentence already has one.","Porque means “because”.","Pero means “but”."]}]};
(LM.QUIZZES = LM.QUIZZES || {})["a2-verbs-imperfect"] = {"version":1,"id":"a2-verbs-imperfect","topic":"a2-verbs-imperfect","level":"A2","title":"Stop: imperfect","passScore":3,"items":[{"id":"a2-verbs-imperfect-q1","type":"multiple-choice","kind":"form","prompt":"Cuando ___ niño, vivía en Sevilla.","options":["fui","era","estaba","soy"],"correct":1,"explanation":"Childhood is a description of the past: ser in the imperfect, era.","optionNotes":["Fui tells a single event; being a child is a background description.",null,"Being a child is not a state with estar.","Soy is the present."]},{"id":"a2-verbs-imperfect-q2","type":"multiple-choice","kind":"form","prompt":"De pequeños, mis hermanos y yo ___ al fútbol todos los días.","options":["jugábamos","jugabamos","jugaban","jugamos"],"correct":0,"explanation":"A habit in the past takes the imperfect. Mis hermanos y yo = nosotros: jugábamos, with an accent.","optionNotes":[null,"The nosotros form of -ar verbs has a written accent: jugábamos.","Jugaban is for ellos; the subject includes yo.","Jugamos is the present or the preterite; a past habit takes the imperfect."]},{"id":"a2-verbs-imperfect-q3","type":"multiple-choice","kind":"form","prompt":"Antes ___ un cine en esta calle.","options":["hay","había","habían","estaba"],"correct":1,"explanation":"Hay in the imperfect is había, for one thing or many.","optionNotes":["Hay is the present; antes needs the past.",null,"Había never changes: había un cine, había muchos cines.","Un cine is new information, so it takes hay / había, not estar."]},{"id":"a2-verbs-imperfect-q4","type":"multiple-choice","kind":"form","prompt":"Cuando era pequeña, mi abuelo ___ historias todas las noches. (contar)","options":["cuentaba","contaba","cuenta","contía"],"correct":1,"explanation":"The imperfect has no stem changes: contar → contaba.","optionNotes":["Stem changes (o → ue) do not happen in the imperfect.",null,"Cuenta is the present.","-ar verbs take -aba, not -ía."]}]};
(LM.QUIZZES = LM.QUIZZES || {})["a2-verbs-present-perfect"] = {"version":1,"id":"a2-verbs-present-perfect","topic":"a2-verbs-present-perfect","level":"A2","title":"Stop: present perfect","passScore":3,"items":[{"id":"a2-verbs-present-perfect-q1","type":"multiple-choice","kind":"form","prompt":"¿___ estado alguna vez en Cuba? (tú)","options":["Has","Hay","Tienes","Eres"],"correct":0,"explanation":"The present perfect is haber + participle: has estado.","optionNotes":[null,"Hay means “there is”.","The helper verb is haber, not tener.","Eres is ser in the present."]},{"id":"a2-verbs-present-perfect-q2","type":"multiple-choice","kind":"form","prompt":"Todavía no he ___ la cena. (hacer)","options":["hacido","hecho","hice","hacer"],"correct":1,"explanation":"Hacer has an irregular participle: hecho.","optionNotes":["Hacer does not take -ido: the participle is hecho.",null,"Hice is the preterite.","After haber comes the participle, not the infinitive."]},{"id":"a2-verbs-present-perfect-q3","type":"multiple-choice","kind":"meaning","prompt":"Which sentence is correct?","options":["Nunca he estado en Chile.","He nunca estado en Chile.","Nunca estado he en Chile.","He estado nunca en Chile."],"correct":0,"explanation":"Nunca goes before haber. After the verb you need no: No he estado nunca en Chile.","optionNotes":[null,"Nothing goes between haber and the participle.","Haber comes before the participle.","Nunca after the verb needs no before it: No he estado nunca."]},{"id":"a2-verbs-present-perfect-q4","type":"multiple-choice","kind":"form","prompt":"Ayer ___ con Marta.","options":["he hablado","hablé","hablo","he hablé"],"correct":1,"explanation":"Ayer is a finished time, so it takes the preterite everywhere.","optionNotes":["Ayer is a finished time: preterite, not the present perfect.",null,"Hablo is the present.","After haber comes the participle: hablado."]}]};
(LM.QUIZZES = LM.QUIZZES || {})["a2-verbs-preterite-irregular"] = {"version":1,"id":"a2-verbs-preterite-irregular","topic":"a2-verbs-preterite-irregular","level":"A2","title":"Stop: irregular preterite","passScore":3,"items":[{"id":"a2-verbs-preterite-irregular-q1","type":"multiple-choice","kind":"form","prompt":"El sábado pasado (yo) ___ al cine con Diego.","options":["fue","fui","fuiste","voy"],"correct":1,"explanation":"Ir in the preterite: fui, fuiste, fue… The yo form is fui.","optionNotes":["Fue is for él, ella, usted.",null,"Fuiste is for tú.","Voy is the present; el sábado pasado needs the past."]},{"id":"a2-verbs-preterite-irregular-q2","type":"multiple-choice","kind":"form","prompt":"Mi hermana ___ la cena anoche. (hacer)","options":["hació","hizó","hizo","hice"],"correct":2,"explanation":"Hacer has the stem hic- and writes hizo with z in the él / ella form. Irregular preterites have no written accent.","optionNotes":["Hacer is irregular: hice, hiciste, hizo.","Irregular preterites have no written accent.",null,"Hice is for yo."]},{"id":"a2-verbs-preterite-irregular-q3","type":"multiple-choice","kind":"form","prompt":"¿Por qué no ___ (tú) venir a la fiesta?","options":["pudiste","podiste","pudistes","pudo"],"correct":0,"explanation":"Poder has the stem pud- in the preterite: pude, pudiste, pudo.","optionNotes":[null,"Poder changes its stem to pud-.","The tú form has no final -s.","Pudo is for él, ella, usted."]},{"id":"a2-verbs-preterite-irregular-q4","type":"multiple-choice","kind":"form","prompt":"Mis padres ___ que sí. (decir)","options":["dijieron","dijeron","decieron","dijo"],"correct":1,"explanation":"Decir has the stem dij-; after j the ellos form ends in -eron: dijeron.","optionNotes":["After j the ending is -eron, not -ieron.",null,"Decir changes its stem to dij-.","Dijo is for él, ella, usted; mis padres = ellos."]}]};
(LM.QUIZZES = LM.QUIZZES || {})["a2-verbs-preterite-regular"] = {"version":1,"id":"a2-verbs-preterite-regular","topic":"a2-verbs-preterite-regular","level":"A2","title":"Stop: regular preterite","passScore":3,"items":[{"id":"a2-verbs-preterite-regular-q1","type":"multiple-choice","kind":"form","prompt":"Ayer Marta ___ con su jefe.","options":["hablo","habló","hablé","hablaste"],"correct":1,"explanation":"Marta = ella. The preterite of hablar for él, ella, usted is habló, with an accent on the o.","optionNotes":["Without the accent, hablo is the present: “I speak”.",null,"Hablé is for yo.","Hablaste is for tú."]},{"id":"a2-verbs-preterite-regular-q2","type":"multiple-choice","kind":"form","prompt":"Anoche (yo) ___ en un restaurante mexicano.","options":["comé","comí","comió","como"],"correct":1,"explanation":"-er and -ir verbs take -í in the yo form of the preterite: comí.","optionNotes":["-é is the -ar ending; -er verbs take -í.",null,"Comió is for él, ella, usted.","Como is the present; anoche needs the past."]},{"id":"a2-verbs-preterite-regular-q3","type":"multiple-choice","kind":"form","prompt":"¿A qué hora ___ (tú) a casa ayer?","options":["llegastes","llegó","llegaste","llegué"],"correct":2,"explanation":"The tú form of the preterite ends in -aste for -ar verbs: llegaste.","optionNotes":["The tú form of the preterite has no final -s.","Llegó is for él, ella, usted.",null,"Llegué is for yo."]},{"id":"a2-verbs-preterite-regular-q4","type":"multiple-choice","kind":"form","prompt":"Ayer (yo) ___ las llaves por toda la casa. (buscar)","options":["buscé","busqué","buscó","busco"],"correct":1,"explanation":"Verbs in -car write -qué in the yo form of the preterite: busqué.","optionNotes":["-car verbs change c to qu before é: busqué.",null,"Buscó is for él, ella, usted.","Busco is the present; ayer needs the past."]}]};
(LM.QUIZZES = LM.QUIZZES || {})["a2-verbs-preterite-vs-imperfect-basics"] = {"version":1,"id":"a2-verbs-preterite-vs-imperfect-basics","topic":"a2-verbs-preterite-vs-imperfect-basics","level":"A2","title":"Stop: indefinido or imperfecto","passScore":3,"items":[{"id":"a2-verbs-preterite-vs-imperfect-basics-q1","type":"multiple-choice","kind":"form","prompt":"Mientras (yo) ___ la cena, sonó el teléfono. (preparar)","options":["preparaba","preparé","preparo","he preparado"],"correct":0,"explanation":"The action in progress is in the imperfect; the event that interrupts it is in the preterite.","optionNotes":[null,"The cooking was in progress when the phone rang: imperfect.","Preparo is the present.","The present perfect does not describe an action in progress."]},{"id":"a2-verbs-preterite-vs-imperfect-basics-q2","type":"multiple-choice","kind":"form","prompt":"Ayer ___ a mi profesora en el supermercado. (ver)","options":["veía","vi","ví","he visto"],"correct":1,"explanation":"One finished action yesterday: preterite. Ver is vi, without an accent.","optionNotes":["Veía describes a habit or a background, not one event.",null,"Vi has no written accent.","Ayer is a finished time: preterite, not the present perfect."]},{"id":"a2-verbs-preterite-vs-imperfect-basics-q3","type":"multiple-choice","kind":"form","prompt":"Cuando era niño, ___ a la playa todos los veranos.","options":["fui","iba","voy","fue"],"correct":1,"explanation":"Todos los veranos is a repeated habit in the past: imperfect, iba.","optionNotes":["A repeated habit takes the imperfect, not the preterite.",null,"Voy is the present.","Fue is for él, ella, usted, and it is the preterite."]},{"id":"a2-verbs-preterite-vs-imperfect-basics-q4","type":"multiple-choice","kind":"form","prompt":"___ las diez cuando llegamos al hotel.","options":["Fueron","Eran","Son","Estaban"],"correct":1,"explanation":"The time is the background of the event: imperfect, eran.","optionNotes":["The time is a background, so it takes the imperfect.",null,"Son is the present.","The time is told with ser, not estar."]}]};
